"use strict";

// Records the data a v0.3.0 user has before upgrading: runs the chat in chat-harness.js through the
// released v0.3.0 artifact (auto translation, plus one message translated with its Translate button) and
// writes what that version saved, for tests/core/cache-compat.test.js to load with the current source:
//   v030-sakura-cache.json  Sakura on a local server, model left on "local-model"
//   v030-remote-cache.json  a remote provider (DeepSeek, fake key)
//
//   node tests/fixtures/make-v030-cache.js <path to DiscordAITranslator-v0.3.0.plugin.js>
//
// The artifact is the one from the v0.3.0 GitHub release (SHA256 below). Its time stamps are rebased
// by the test, so the fixtures never go stale.
const crypto = require("node:crypto");
const fs = require("node:fs");
const path = require("node:path");
const {
    CHAT_MESSAGES,
    createV030Settings,
    createFakeDataApi,
    createFakeLocalServer,
    mountChat,
    installChatGlobals,
    startChatPlugin
} = require("./chat-harness");

const V030_SHA256 = "f61b3775475d1380b7b240116d4ac36a9267c6ee94eecf75edd22f8380a63c6b";
const VARIANTS = [
    { file: "v030-sakura-cache.json", remote: false, label: "Sakura, model local-model" },
    { file: "v030-remote-cache.json", remote: true, label: "DeepSeek with a fake key" }
];

async function record(Plugin, variant, sha256) {
    const bdApi = createFakeDataApi({ DiscordAITranslator: { settings: createV030Settings({ remote: variant.remote }) } });
    const globals = installChatGlobals({ bdApi });
    try {
        const server = createFakeLocalServer();
        const chat = mountChat(globals.document, CHAT_MESSAGES);
        const { plugin, scanUntilIdle, lineText, translate } = startChatPlugin(Plugin, { server, chat });
        if (typeof plugin.migrateLegacyDataStores === "function") throw new Error("this is not v0.3.0");

        await scanUntilIdle();
        for (const message of CHAT_MESSAGES.filter(item => item.manual)) {
            await translate(message.id);
            if (lineText(message.id) !== message.translation) throw new Error(`v0.3.0 did not translate ${message.id}`);
        }
        // Scrolled back: v0.3.0 draws every line from its cache.
        const requests = server.log.length;
        chat.remount();
        await scanUntilIdle();
        if (server.log.length !== requests) throw new Error("v0.3.0 requested a cached message again");
        const missing = CHAT_MESSAGES.filter(message => !message.manual && lineText(message.id) !== message.translation);
        if (missing.length) throw new Error(`v0.3.0 did not draw ${missing.map(message => message.id).join(", ")}`);

        plugin.translationCacheDirty = true;
        if (plugin.flushTranslationCache({ retryOnError: false }) !== true) throw new Error("v0.3.0 did not save its cache");
        plugin.flushSettings?.({ retryOnError: false });
        plugin.stop();

        const saved = bdApi.files.DiscordAITranslator;
        const fixture = {
            description: `What DiscordAITranslator v0.3.0 saved for the chat in tests/fixtures/chat-harness.js (${variant.label}). Generated by tests/fixtures/make-v030-cache.js; all text is invented.`,
            plugin: { version: "0.3.0", sha256 },
            requests: server.log,
            data: { DiscordAITranslator: { settings: saved.settings, translationCache: saved.translationCache } }
        };
        const output = path.join(__dirname, variant.file);
        fs.writeFileSync(output, `${JSON.stringify(fixture, null, 2)}\n`);
        process.stdout.write(`${path.relative(process.cwd(), output)}: ${saved.translationCache.entries.length} cache entries, `
            + `${server.chatPhrases().length} chat requests, ${server.modelRequests()} model lookups\n`);
    }
    finally {
        globals.restore();
    }
}

async function main() {
    const artifactPath = process.argv[2] || process.env.DAIT_V030_ARTIFACT || "";
    if (!artifactPath) throw new Error("usage: node tests/fixtures/make-v030-cache.js <DiscordAITranslator-v0.3.0.plugin.js>");
    const sha256 = crypto.createHash("sha256").update(fs.readFileSync(artifactPath)).digest("hex");
    if (sha256 !== V030_SHA256) throw new Error(`not the released v0.3.0 artifact (sha256 ${sha256})`);
    const Plugin = require(path.resolve(artifactPath));
    for (const variant of VARIANTS) await record(Plugin, variant, sha256);
}

main().catch(error => {
    process.stderr.write(`${error.stack || error}\n`);
    process.exit(1);
});
